// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        address original = c.owner();
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (!ok) {
            assertTrue(c.owner() == original);
        } else {
            assertTrue(c.owner() == original, "non-owner must not change owner");
        }
    }
}
